"""Single-page command center for the hackathon demo."""

PAGE = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NightShift — Autonomous maintenance</title><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Instrument+Serif:ital@0;1&family=Manrope:wght@500;600;700&display=swap');*{box-sizing:border-box}body{margin:0;background:#f5f3ee;color:#20231e;font-family:Manrope,system-ui;min-height:100vh}.shell{max-width:1280px;margin:auto;padding:28px 38px 55px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d9d8d1;padding-bottom:20px}.brand{display:flex;gap:10px;align-items:center;font-weight:700;letter-spacing:-.5px;font-size:18px}.bolt{display:grid;place-items:center;width:29px;height:29px;border-radius:50%;background:#252a23;color:#f5f3ee;font-family:Instrument Serif;font-size:20px}.live{font:11px 'DM Mono';color:#6e746b;display:flex;gap:8px;align-items:center}.live i{width:7px;height:7px;border-radius:99px;background:#6b9e68}.hero{display:flex;justify-content:space-between;gap:30px;padding:62px 0 42px}.eyebrow{font:11px 'DM Mono';letter-spacing:1px;color:#69764c;text-transform:uppercase}.hero h1{font-family:Instrument Serif,serif;font-weight:400;font-size:clamp(45px,6vw,76px);line-height:.92;letter-spacing:-2.5px;margin:18px 0;max-width:770px}.hero h1 em{font-style:italic;color:#687c4e}.hero p{color:#62675f;max-width:480px;line-height:1.65;font-size:14px}.button{align-self:end;background:#252a23;color:#f6f5ef;border:0;border-radius:4px;padding:13px 17px;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:1.45fr .55fr;gap:16px}.card{background:#fbfaf6;border:1px solid #d9d8d1;border-radius:5px;padding:23px}.label{font:10px 'DM Mono';color:#7a8077;text-transform:uppercase;letter-spacing:.9px}.issue{display:flex;justify-content:space-between;margin-top:15px}.issue h2{margin:4px 0;font-size:21px;letter-spacing:-.7px}.tag{height:max-content;font:10px 'DM Mono';padding:6px 8px;border-radius:3px;background:#edf0e6;color:#61704b}.timeline{margin-top:25px;border-left:1px solid #d7d8d1;padding-left:20px}.step{position:relative;margin:0 0 19px}.step:before{content:'';position:absolute;left:-25px;top:3px;width:8px;height:8px;border-radius:50%;background:#d7d8d1;border:3px solid #fbfaf6}.step.done:before{background:#6b9e68}.step.active:before{background:#b48a57}.step b{display:block;font-size:13px}.step span{font-size:12px;color:#7a8077}.status{display:flex;gap:11px;align-items:center;background:#f0f0ea;border-radius:3px;padding:12px;margin-top:17px}.status strong{font-size:13px}.status small{color:#7a8077;display:block}.gauge{margin-left:auto;color:#5d794d;font:16px 'DM Mono'}.policy{display:grid;gap:8px;margin-top:16px}.check{display:flex;justify-content:space-between;padding:11px;background:#f3f2ed;border-radius:3px;font-size:12px}.check span:last-child{color:#5d794d;font-family:'DM Mono'}.side h3{font-size:17px;margin:7px 0 16px}.metric{padding:16px 0;border-bottom:1px solid #e2e1da}.metric strong{font-family:Instrument Serif;font-weight:400;font-size:37px;letter-spacing:-1px}.metric small{display:block;color:#7a8077;margin-top:3px}.pr{margin-top:18px;background:#e8ece1;border:1px solid #d4dbc8;border-radius:4px;padding:14px}.pr b{font-size:13px}.pr p{font:11px 'DM Mono';color:#63715c}.bar{height:3px;background:#d3d8cb;border-radius:5px;overflow:hidden;margin-top:9px}.bar i{display:block;width:78%;height:100%;background:#6b7e52}@media(max-width:800px){.shell{padding:20px}.hero{display:block}.button{margin-top:15px}.grid{grid-template-columns:1fr}.hero h1{letter-spacing:-2px}}
</style></head><body><main class="shell"><header class="top"><div class="brand"><div class="bolt">ϟ</div> NIGHTSHIFT</div><div class="live"><i></i> SYSTEMS OPERATIONAL · US-CENTRAL1</div></header><section class="hero"><div><div class="eyebrow">Autonomous maintenance command center</div><h1>From approved issue<br>to <em>tested draft PR.</em></h1><p>NightShift works in the background, keeping every decision visible, bounded, and ready for human review.</p></div><button class="button" onclick="document.querySelector('.active').scrollIntoView({behavior:'smooth'})">View live run →</button></section><section class="grid"><article class="card"><div class="label">Current autonomous run</div><div class="issue"><div><h2>Empty search results crash the page</h2><span class="label">Issue #42 · karthik7271/nightshift</span></div><span class="tag">agent-ready</span></div><div class="timeline"><div class="step done"><b>Issue qualified</b><span>Approved repository · bounded bug label</span></div><div class="step done"><b>Context assembled</b><span>2 source files · 1 regression test</span></div><div class="step active"><b>Plan verified</b><span>Awaiting isolated branch creation</span></div><div class="step"><b>Run CI</b><span>GitHub Actions check suite</span></div><div class="step"><b>Open draft PR</b><span>Human merge required</span></div></div><div class="status"><div><strong>Scope confidence</strong><small>All deterministic policy gates passed</small></div><div class="gauge">92%</div></div></article><aside class="card side"><div class="label">Safety posture</div><h3>Autonomy you can audit</h3><div class="policy"><div class="check"><span>Branch isolation</span><span>PASS</span></div><div class="check"><span>Max 3 changed files</span><span>PASS</span></div><div class="check"><span>No auth / CI / dependency edits</span><span>PASS</span></div><div class="check"><span>Human merge authority</span><span>ENFORCED</span></div></div><div class="metric"><strong>0</strong><small>unbounded actions taken</small></div><div class="metric"><strong>1</strong><small>approval required before merge</small></div><div class="pr"><b>Draft PR will include</b><p>change summary · CI evidence · risk notes · rollback guidance</p><div class="bar"><i></i></div></div></aside></section></main></body></html>'''
